===== gbnf/rules_builder/parse_char.py
from __future__ import annotations

from typing import Tuple

from ..utils.errors.grammar_parse_error import GrammarParseError
from ..utils.js import char_at, parse_int_hex


def parse_char(src: str, pos: int) -> Tuple[int, int]:
    if char_at(src, pos) == '\\':
        escape = char_at(src, pos + 1)
        if escape in ('x', 'u', 'U'):
            width = {'x': 4, 'u': 6, 'U': 10}[escape]
            code_point = parse_int_hex(src[pos + 2:pos + width])
            if code_point is None:
                raise GrammarParseError(src, pos, f'Invalid escape at {char_at(src, pos)}')
            return (code_point, width)
        if escape == 't':
            return (ord('\t'), 2)
        if escape == 'r':
            return (ord('\r'), 2)
        if escape == 'n':
            return (ord('\n'), 2)
        if escape in ('"', '[', ']'):
            return (ord(src[pos + 1]), 2)
        if escape == '\\':
            code_point = char_at(src, pos + 1)
            if code_point == '':
                raise GrammarParseError(src, pos, 'Could not get code point for character')
            return (ord(code_point), 2)
        raise GrammarParseError(src, pos, f'Unknown escape at {char_at(src, pos)}')

    if not char_at(src, pos):
        raise GrammarParseError(src, pos, 'Unexpected end of grammar input, failed to complete parse')
    return (ord(src[pos]), 1)
===== gbnf/rules_builder/parse_name.py
from __future__ import annotations

import re

from ..utils.errors.grammar_parse_error import GrammarParseError

PARSE_NAME_ERROR = 'Failed to find a valid name'


def GET_INVALID_CHAR_ERROR(char: str) -> str:
    return (
        f'Invalid character "{char}" when parsing name, '
        'only lowercase letters and hyphens are allowed.'
    )


_VALID_CHAR = re.compile(r'[a-zA-Z-]')
_INVALID_NEXT_CHAR = re.compile(r'[_0-9]')


def parse_name(grammar: str, pos: int) -> str:
    name = ''
    while pos < len(grammar) and _VALID_CHAR.search(grammar[pos]):
        name += grammar[pos]
        pos += 1
    if not name:
        raise GrammarParseError(grammar, pos, PARSE_NAME_ERROR)
    if pos < len(grammar) and _INVALID_NEXT_CHAR.search(grammar[pos]):
        raise GrammarParseError(grammar, pos, GET_INVALID_CHAR_ERROR(grammar[pos]))
    return name
===== gbnf/rules_builder/parse_space.py
from __future__ import annotations

from ..utils.js import char_at


def parse_space(src: str, pos: int, newline_ok: bool) -> int:
    while char_at(src, pos) in (' ', '\t', '#') or (
        newline_ok and char_at(src, pos) in ('\r', '\n')
    ):
        if char_at(src, pos) == '#':
            while char_at(src, pos) and char_at(src, pos) not in ('\r', '\n'):
                pos += 1
        else:
            pos += 1
    return pos
===== gbnf/rules_builder/rules_builder.py
from __future__ import annotations

import re
import time
from typing import List, Optional

from ..utils.errors.grammar_parse_error import GrammarParseError
from ..utils.js import char_at
from .is_word_char import is_word_char
from .parse_char import parse_char
from .parse_name import parse_name
from .parse_space import parse_space
from .symbol_ids import SymbolIds
from .types import InternalRuleDef, InternalRuleType

_WHITESPACE = re.compile(r'\s')


class RulesBuilder:
    def __init__(self, src: str, limit: float = 1000):
        self.pos = 0
        self.symbol_ids = SymbolIds()
        self.rules: List[Optional[List[InternalRuleDef]]] = []
        self.src = src
        self.start = time.perf_counter() * 1000
        self._time_limit = limit
        self._parse(src)

    def _parse(self, src: str) -> None:
        # move cursor forward until we reach non-whitespace content
        self.pos = parse_space(src, 0, True)

        while self.pos < len(src):
            self._parse_rule(src)

        # Validate the state to ensure that all rules are defined
        for rule in self.rules:
            if rule is None:
                continue
            for elem in rule:
                if elem.type == InternalRuleType.RULE_REF:
                    # Ensure that the rule at that location exists
                    referenced = self.rules[elem.value] if elem.value < len(self.rules) else None
                    rule_exists = referenced is not None and len(referenced) > 0
                    if not rule_exists:
                        missing_rule_name = self.symbol_ids.reverse_get(elem.value)
                        missing_rule_pos = self.symbol_ids.get_pos(missing_rule_name)

                        # Skip over the ::= and any whitespace
                        while missing_rule_pos < len(src) and (
                            src[missing_rule_pos] in (':', '=')
                            or _WHITESPACE.search(src[missing_rule_pos])
                        ):
                            missing_rule_pos += 1

                        raise GrammarParseError(
                            src,
                            missing_rule_pos,
                            f'Undefined rule identifier "{missing_rule_name}"',
                        )

    def _parse_rule(self, src: str) -> None:
        name = parse_name(src, self.pos)
        self.pos = parse_space(src, self.pos + len(name), False)
        rule_id = self.get_symbol_id(name, len(name))

        # Skip over whitespace characters and find the ::= sequence
        self.pos = parse_space(src, self.pos, True)
        if not (
            char_at(src, self.pos) == ':'
            and char_at(src, self.pos + 1) == ':'
            and char_at(src, self.pos + 2) == '='
        ):
            raise GrammarParseError(src, self.pos, f'Expecting ::= at {self.pos}')
        self.pos = parse_space(src, self.pos + 3, True)

        self.parse_alternates(name, rule_id)

        if char_at(src, self.pos) == '\r':
            self.pos += 2 if char_at(src, self.pos + 1) == '\n' else 1
        elif char_at(src, self.pos) == '\n':
            self.pos += 1
        elif char_at(src, self.pos):
            raise GrammarParseError(src, self.pos, f'Expecting newline or end at {self.pos}')
        self.pos = parse_space(src, self.pos, True)

    def get_symbol_id(self, src: str, length: int) -> int:
        next_id = self.symbol_ids.size
        key = src[0:length]
        if not self.symbol_ids.has(key):
            self.symbol_ids.set(key, next_id, self.pos)
        return self.symbol_ids.get(key)

    def generate_symbol_id(self, base_name: str) -> int:
        next_id = self.symbol_ids.size
        self.symbol_ids.set(f'{base_name}_{next_id}', next_id, self.pos)
        return next_id

    def add_rule(self, rule_id: int, rule: List[InternalRuleDef]) -> None:
        # `rules` is a sparse array in the reference implementation; growing it
        # with `None` keeps ids stable and holes detectable.
        while len(self.rules) <= rule_id:
            self.rules.append(None)
        self.rules[rule_id] = rule

    def check_duration(self) -> None:
        if time.perf_counter() * 1000 - self.start > self._time_limit:
            raise GrammarParseError(
                self.src, self.pos, f'duration of {self._time_limit} exceeded:'
            )

    def parse_sequence(
        self,
        rule_name: str,
        out_elements: List[InternalRuleDef],
        depth: int = 0,
    ) -> None:
        is_nested = depth != 0
        src = self.src
        last_sym_start = len(out_elements)
        while char_at(src, self.pos):
            if char_at(src, self.pos) == '"':
                self.pos += 1
                last_sym_start = len(out_elements)
                while char_at(src, self.pos) != '"':
                    self.check_duration()
                    value, inc_pos = parse_char(src, self.pos)
                    out_elements.append(InternalRuleDef(InternalRuleType.CHAR, [value]))
                    # Adjusting pos by the length of parsed characters
                    self.pos += inc_pos
                self.pos = parse_space(src, self.pos + 1, is_nested)
            elif char_at(src, self.pos) == '[':
                self.pos += 1
                start_type = InternalRuleType.CHAR
                if char_at(src, self.pos) == '^':
                    self.pos += 1
                    start_type = InternalRuleType.CHAR_NOT
                last_sym_start = len(out_elements)
                while char_at(src, self.pos) != ']':
                    self.check_duration()
                    type_ = (
                        InternalRuleType.CHAR_ALT
                        if last_sym_start < len(out_elements)
                        else start_type
                    )
                    startchar_value, inc_pos = parse_char(src, self.pos)
                    self.pos += inc_pos
                    if type_ in (InternalRuleType.CHAR, InternalRuleType.CHAR_NOT):
                        out_elements.append(InternalRuleDef(type_, [startchar_value]))
                    else:
                        out_elements.append(InternalRuleDef(type_, startchar_value))

                    if char_at(src, self.pos) == '-' and char_at(src, self.pos + 1) != ']':
                        self.pos += 1
                        endchar_value, inc_pos = parse_char(src, self.pos)
                        out_elements.append(
                            InternalRuleDef(InternalRuleType.CHAR_RNG_UPPER, endchar_value)
                        )
                        self.pos += inc_pos
                self.pos = parse_space(src, self.pos + 1, is_nested)
            elif is_word_char(char_at(src, self.pos)):
                name = parse_name(src, self.pos)
                ref_rule_id = self.get_symbol_id(name, len(name))
                self.pos += len(name)
                self.pos = parse_space(src, self.pos, is_nested)

                last_sym_start = len(out_elements)
                out_elements.append(InternalRuleDef(InternalRuleType.RULE_REF, ref_rule_id))
            elif char_at(src, self.pos) == '(':
                self.pos = parse_space(src, self.pos + 1, True)
                sub_rule_id = self.generate_symbol_id(rule_name)
                self.parse_alternates(rule_name, sub_rule_id, depth + 1)
                last_sym_start = len(out_elements)
                out_elements.append(InternalRuleDef(InternalRuleType.RULE_REF, sub_rule_id))
                if char_at(src, self.pos) != ')':
                    raise GrammarParseError(src, self.pos, f"Expecting ')' at {self.pos}")
                self.pos = parse_space(src, self.pos + 1, is_nested)
            elif char_at(src, self.pos) in ('*', '+', '?'):
                if last_sym_start == len(out_elements):
                    raise GrammarParseError(
                        src, self.pos, f'Expecting preceding item to */+/? at {self.pos}'
                    )
                sub_rule_id = self.generate_symbol_id(rule_name)
                sub_rule: List[InternalRuleDef] = out_elements[last_sym_start:]
                if char_at(src, self.pos) in ('*', '+'):
                    sub_rule.append(InternalRuleDef(InternalRuleType.RULE_REF, sub_rule_id))
                sub_rule.append(InternalRuleDef(InternalRuleType.ALT))
                if char_at(src, self.pos) == '+':
                    sub_rule.extend(out_elements[last_sym_start:])
                sub_rule.append(InternalRuleDef(InternalRuleType.END))
                self.add_rule(sub_rule_id, sub_rule)
                del out_elements[last_sym_start:]
                out_elements.append(InternalRuleDef(InternalRuleType.RULE_REF, sub_rule_id))
                self.pos = parse_space(src, self.pos + 1, is_nested)
            else:
                break

    def parse_alternates(
        self,
        rule_name: str,
        rule_id: int,
        depth: int = 0,
    ) -> None:
        src = self.src
        rule: List[InternalRuleDef] = []
        self.parse_sequence(rule_name, rule, depth)
        while char_at(src, self.pos) == '|':
            self.check_duration()
            rule.append(InternalRuleDef(InternalRuleType.ALT))
            self.pos = parse_space(src, self.pos + 1, True)
            self.parse_sequence(rule_name, rule, depth)
        rule.append(InternalRuleDef(InternalRuleType.END))
        self.add_rule(rule_id, rule)
