      } else {
        // `isGraphPointerRuleRef` has already established the rule's type.
        for (const node of (this.node.rule as RuleRef).nodes) {
          yield* new GraphPointer(node, this).resolve();
        }
      }
    } else if (isGraphPointerRuleEnd(this)) {
      if (this.parent === undefined) {
        yield this;
      } else {
        yield* this.parent.resolve(true);
      }
    } else if (isGraphPointerRuleChar(this) || isGraphPointerRuleCharExclude(this)) {
      yield this;
    } else {
      throw new Error(`Unknown rule: ${this.node.rule}`);
    }
  }

  *fetchNext(): IterableIterator<GraphPointer> {
    // if this pointer is invalid, then we don't return any new pointers
    if (this._valid === false) {
      return;
    }

    // if this pointer is an end node, we return the parent's next node. If no parent
    // exists, we return nothing, since it's the end of the line.
    if (isRuleEnd(this.node.rule)) {
      if (this.parent !== undefined) {
        yield* this.parent.fetchNext();
      }
    } else {
      if (this.node.next === undefined) {
        throw new Error(`No next node: ${this.node}`);
      }
      const pointer = new GraphPointer(this.node.next, this.parent);
      yield* pointer.resolve();
    }
  }

  get rule(): UnresolvedRule {
    return this.node.rule;
  }

  get valid(): boolean | undefined {
    return this._valid;
  }

  set valid(valid: boolean | undefined) {
    this._valid = valid;
  }

  print(colorize: Colorize = defaultColorize): string {
    return printGraphPointer(this, colorize);
  }

  toString(): string {
    return this.print(defaultColorize);
  }
}

import { GrammarParseError } from '../utils/errors/grammar-parse-error.js';

const ESCAPE_WIDTHS: Record<string, number> = {
  x: 4,
  u: 6,
  U: 10,
};

export const parseChar = (src: string, pos: number): [number, number] => {
  if (src[pos] === '\\') {
    const escape = src[pos + 1];
    switch (escape) {
      case 'x':
      case 'u':
      case 'U': {
        const width = ESCAPE_WIDTHS[escape];
        const codePoint = parseInt(src.slice(pos + 2, pos + width), 16);
        if (Number.isNaN(codePoint)) {
          throw new GrammarParseError(src, pos, `Invalid escape at ${src[pos]}`);
        }
        return [codePoint, width];
      }
      case 't':
        return ['\t'.charCodeAt(0), 2];
      case 'r':
        return ['\r'.charCodeAt(0), 2];
      case 'n':
        return ['\n'.charCodeAt(0), 2];
      case '"':
      case '[':
      case ']':
        return [src.charCodeAt(pos + 1), 2];
      case '\\': {
        const codePoint = src[pos + 1];
        if (codePoint === undefined) {
          throw new GrammarParseError(src, pos, 'Could not get code point for character');
        }
        return [codePoint.charCodeAt(0), 2];
      }
      default:
        throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
    }
  }

  if (!src[pos]) {
    throw new GrammarParseError(
      src,
      pos,
      'Unexpected end of grammar input, failed to complete parse',
    );
  }
  return [src.charCodeAt(pos), 1];
};

export enum RuleType {
  CHAR = 'char',
  CHAR_EXCLUDE = 'char_exclude',
  END = 'end',
}

// A range is a two element [start, end] pair of code points.
export type Range = [number, number];
export type RuleValue = number | Range;
// ValidInput can either be a string, or a number indicating a code point.
// It CANNOT be a number representing a number; a number being a "number"
// (like "8") should be passed in as a string.
export type ValidInput = string | number | number[];

export interface RuleCharJSON { type: RuleType.CHAR; value: RuleValue[] }
export interface RuleCharExcludeJSON { type: RuleType.CHAR_EXCLUDE; value: RuleValue[] }
export interface RuleEndJSON { type: RuleType.END }
export type RuleJSON = RuleCharJSON | RuleCharExcludeJSON | RuleEndJSON;

/**
 * Base class for the rules exposed to consumers of a `ParseState`.
 *
 * Rules are compared by reference; the graph relies on that to dedupe and to
 * group pointers.
 */
export abstract class AbstractRule {
  abstract readonly type: RuleType;

  abstract toJSON(): RuleJSON;

  serialize(): string {
    return JSON.stringify(this.toJSON());
  }
}

abstract class RuleWithValue extends AbstractRule {
  value: RuleValue[];

  constructor(value: RuleValue[] = []) {
    super();
    this.value = value.map(v => (Array.isArray(v) ? ([...v] as Range) : v));
  }

  toString(): string {
    return `${this.constructor.name}(${JSON.stringify(this.value)})`;
  }
}

export class RuleChar extends RuleWithValue {
  readonly type = RuleType.CHAR;

  toJSON(): RuleCharJSON {
    return { type: this.type, value: this.value };
  }
}

export class RuleCharExclude extends RuleWithValue {
  readonly type = RuleType.CHAR_EXCLUDE;

  toJSON(): RuleCharExcludeJSON {
    return { type: this.type, value: this.value };
  }
}

export class RuleEnd extends AbstractRule {
  readonly type = RuleType.END;

  toJSON(): RuleEndJSON {
    return { type: this.type };
  }

  toString(): string {
    return 'RuleEnd()';
  }
}

export type Rule = RuleChar | RuleCharExclude | RuleEnd;

