// Emit ported-implementation results for the differential harness.
import { readFileSync } from 'node:fs';
import GBNF from '/workspace/ported_implementation/src/index.ts';

const describeExc = (exc: unknown) => {
  const error = exc as Error;
  // Python surfaces internal invariant violations as ValueError; the port uses Error.
  const name = error.name === 'Error' ? 'ValueError' : error.name;
  return { error: name, message: error.message };
};

const walk = (grammar: string, inputs: string[]) => {
  const out: unknown[] = [];
  for (const input of inputs) {
    const steps: unknown[] = [];
    try {
      let state = GBNF(grammar);
      steps.push([...state].map(rule => rule.toJSON()));
      for (const char of input.split('')) {
        state = state.add(char);
        steps.push([...state].map(rule => rule.toJSON()));
      }
      out.push({ input, steps });
    } catch (exc) {
      out.push({ input, steps, ...describeExc(exc) });
    }
  }
  return out;
};

const cases: [string, string[]][] = JSON.parse(readFileSync('/workspace/diff/cases.json', 'utf8'));
const errorCases: string[] = JSON.parse(readFileSync('/workspace/diff/error_cases.json', 'utf8'));

const results: Record<string, unknown[]> = { walks: [], errors: [], prints: [], whole: [] };

for (const [grammar, inputs] of cases) {
  results.walks.push({ grammar, runs: walk(grammar, inputs) });

  const whole: unknown[] = [];
  for (const input of inputs) {
    try {
      const state = GBNF(grammar, input);
      whole.push({
        input,
        rules: [...state].map(rule => rule.toJSON()),
        size: state.size,
        repr: state.toString(),
      });
    } catch (exc) {
      whole.push({ input, ...describeExc(exc) });
    }
  }
  results.whole.push({ grammar, runs: whole });

  try {
    const state = GBNF(grammar);
    results.prints.push({ grammar, print: (state as any).graph.print() });
  } catch (exc) {
    results.prints.push({ grammar, ...describeExc(exc) });
  }
}

for (const grammar of errorCases) {
  try {
    const state = GBNF(grammar);
    results.errors.push({ grammar, ok: state.toString() });
  } catch (exc) {
    results.errors.push({ grammar, ...describeExc(exc) });
  }
}

process.stdout.write(JSON.stringify(results, null, 1));

