"""Compare reference vs ported output, ignoring known-irrelevant fields."""
import json

with open('/workspace/diff/py.json') as f:
    py = json.load(f)
with open('/workspace/diff/ts.json') as f:
    ts = json.load(f)

diffs = []


def compare(path, a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        a = {k: v for k, v in a.items() if k != 'traceback'}
        b = {k: v for k, v in b.items() if k != 'traceback'}
        for key in sorted(set(a) | set(b)):
            if key not in a or key not in b:
                diffs.append((path, f'key {key}: py={a.get(key)!r} ts={b.get(key)!r}'))
            else:
                compare(f'{path}.{key}', a[key], b[key])
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            diffs.append((path, f'length py={len(a)} ts={len(b)}'))
        for i, (x, y) in enumerate(zip(a, b)):
            compare(f'{path}[{i}]', x, y)
    elif a != b:
        diffs.append((path, f'py={a!r} ts={b!r}'))


for section in ['walks', 'whole', 'prints', 'errors']:
    compare(section, py[section], ts[section])

print(f'{len(diffs)} differences')
for path, detail in diffs[:60]:
    print(f'  {path}: {detail}')

